from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
bank=json.loads((ROOT/'data/bank.json').read_text())
# The reader contains corpus data locally. AI retrieval uses bank.py and never opens this full page.
minimal={k:bank[k] for k in ['display_name','parents','items','rubrics']}
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>2026海淀一模 · 题库试用</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#f3f5f7;color:#172738;font-family:-apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif;font-size:15px}header{padding:24px 32px;background:#173951;color:white}header h1{font-size:25px;margin:0 0 10px}header p{margin:0;color:#d5e3eb;line-height:1.6}.layout{display:grid;grid-template-columns:250px minmax(0,920px);gap:24px;max-width:1240px;margin:24px auto;padding:0 20px}aside{position:sticky;top:20px;align-self:start;max-height:90vh;overflow:auto}select,input{width:100%;padding:10px;margin:0 0 10px;border:1px solid #cbd5df;border-radius:7px;background:white;font:inherit}nav button{display:block;width:100%;text-align:left;border:0;border-bottom:1px solid #d8e0e6;background:transparent;padding:11px;cursor:pointer;color:#19374c}nav button.active{background:#dbeaf5;border-radius:6px}nav small{display:block;color:#63768a;margin-top:4px}.card{padding:32px 42px;background:white;border:1px solid #dce3e8;border-radius:10px;margin-bottom:18px;box-shadow:0 2px 8px #17395108}h2{font-size:23px;margin:0 0 12px}h3{font-size:18px;color:#214864;margin:24px 0 12px}.meta,.limits{font-size:13px;line-height:1.7;color:#617080}.limits{background:#f4f7f9;padding:12px;border-left:3px solid #8ea7bc}.question{font-family:"Songti SC",SimSun,serif;font-size:16px;line-height:1.55;color:#111}.question.subjective{font-family:KaiTi,"Kaiti SC",STKaiti,serif}.question p{margin:9px 0;text-indent:2em}.question .prompt{font-family:"Songti SC",SimSun,serif;margin-top:17px}.question .note{font-size:12px;line-height:1.5;text-indent:0;margin:5px auto 16px;width:94%}.grid{display:grid;grid-template-columns:1fr 1fr;column-gap:24px;row-gap:7px;margin:12px 0}.grid div{padding-left:1.8em;text-indent:-1.8em}.box{border:1px dotted #333;padding:10px 15px;margin:12px 0}.box p{margin:4px 0;text-indent:0}.parallel{display:grid;grid-template-columns:1fr 1fr;gap:24px}.parallel .box{border:1px solid #333}.float-right{float:right;width:48%;margin:0 0 10px 18px;font-size:15px}.question:after{content:"";display:table;clear:both}figure{margin:12px auto;max-width:100%;text-align:center}figure img{width:100%;height:auto;object-fit:contain}figcaption{font-size:12px;color:#5d6f7b}.question table,.rubric table{border-collapse:collapse;width:100%;font-size:15px;margin:14px 0;line-height:1.65}.question th,.question td,.rubric th,.rubric td{border:1px solid #8d969b;padding:8px 10px;vertical-align:top}.question th,.rubric th{background:#edf4f8}.rubric{font-family:"Songti SC",SimSun,serif;font-size:15px;line-height:1.75}.rubric p{margin:9px 0}.rubric .asset{max-width:100%;display:block;margin:12px auto}.rubric .excerpt{white-space:pre-wrap}.source img{display:block;width:100%;height:auto;margin:12px 0}.source summary,details summary{cursor:pointer;color:#246083;margin:10px 0}a{color:#22658a}.tag{display:inline-block;padding:2px 7px;background:#eef4f8;color:#335c77;border-radius:4px;margin:2px}.result{color:#173951;font-size:17px;margin:18px 0;padding:12px 15px;background:#f0f6f9}.small{font-size:12px;color:#697985}footer{font-size:12px;line-height:1.8;color:#617487;margin:25px 0}@media(max-width:760px){.layout{grid-template-columns:1fr}.card{padding:22px}aside{position:relative;max-height:250px}.float-right{float:none;width:auto;margin:12px 0}.grid{column-gap:12px}}@media print{header,aside,.source,.meta,footer,.limits,.small{display:none}.layout{display:block;margin:0}.card{border:0;box-shadow:none;padding:0}.question{font-size:10.5pt;line-height:16pt}figure,table,.box{break-inside:avoid}h3{break-after:avoid}}
</style><header><h1>2026海淀一模 · 题库试用</h1><p>21 道大题，24 个可独立取用的题包。选择题、分问材料、评分表与原图已配对。<br>用于检验共享题库；未写入任何宝典。题肢单练另需按册逐条审核。</p></header><div class="layout"><aside><select id="module" aria-label="按教材筛选"><option value="">全部教材</option></select><input id="search" placeholder="搜索题号、考点" aria-label="搜索题号或考点"><div id="count" class="small"></div><nav id="nav"></nav><footer>数据：本地原卷 8 页、评分材料 8 页。<br>这里供人工浏览；制作宝典时用按题取用包，不必把整页题库读入模型。</footer></aside><main id="main"></main></div><script>
const B=__BANK__;const P=Object.fromEntries(B.parents.map(x=>[x.number,x]));const R=Object.fromEntries(B.rubrics.map(x=>[x.id,x]));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function table(b){let out=b.caption?'<p><strong>'+esc(b.caption)+'</strong></p>':'';out+='<table>';for(const [section,rows] of [['header',b.headers?.length?[b.headers]:[]],['body',b.rows||[]]]){const covered=new Set(),merges=new Map();for(const m of b.merged_cells||[]){if(m.section!==section)continue;merges.set(m.row+','+m.col,m);for(let r=m.row;r<m.row+m.rowspan;r++)for(let c=m.col;c<m.col+m.colspan;c++)if(r!==m.row||c!==m.col)covered.add(r+','+c);}rows.forEach((row,r)=>{out+='<tr>';row.forEach((v,c)=>{if(covered.has(r+','+c))return;const m=merges.get(r+','+c),tag=section==='header'?'th':'td';out+='<'+tag+(m?' rowspan="'+m.rowspan+'" colspan="'+m.colspan+'"':'')+'>'+esc(v).replaceAll('\\n','<br>')+'</'+tag+'>';});out+='</tr>';});}return out+'</table>';}
function block(b){const t=b.type;let title=b.text?esc(b.text):'';if(['statements','options'].includes(t))return '<div class="grid">'+b.entries.map(x=>'<div>'+esc(x.label)+'．'+esc(x.text)+'</div>').join('')+'</div>';if(t==='table')return (title?'<p>'+title+'</p>':'')+table(b);if(t==='figure')return '<figure style="width:'+Math.round((b.layout?.width_fraction_of_content||.78)*100)+'%"><img src="'+esc(b.asset)+'" alt="'+esc(b.caption||b.alt)+'"></figure>';if(t==='parallel_boxes')return '<div class="parallel">'+b.paragraphs.map(x=>'<div class="box">'+esc(x)+'</div>').join('')+'</div>';if(t==='boxed_text')return '<div class="box '+(b.layout?.position==='float-right'?'float-right':'')+'">'+(title?'<strong>'+title+'</strong>':'')+(b.paragraphs||[]).map(x=>'<p>'+esc(x)+'</p>').join('')+'</div>';return '<p class="'+(t==='note'?'note':t==='prompt'?'prompt':'')+'">'+title+'</p>';}
function rubric(r){let s='',lastRole=null;const names={reference_answer:'载体中的参考答案原文',scoring_rule:'正式评分条件原文',official_example:'评分载体提供的示例'};for(const b of r.blocks.filter(b=>b.type!=='student_example')){if(b.role!==lastRole){s+='<h3>'+esc(names[b.role]||'载体原文')+'</h3>';lastRole=b.role;}s+=b.type==='table'?table(b):'<p class="excerpt">'+esc(b.text||'')+'</p>';}s+='<p class="small">评分原页：'+r.source_pages.map(p=>'<a href="assets/pages/细则/p'+String(p).padStart(2,'0')+'.png" target="_blank">第 '+p+' 页</a>').join(' · ')+'</p>';if(r.student_examples?.length)s+='<details><summary>学生样卷与阅卷批注（独立保留）</summary>'+r.student_examples.map(x=>'<img class="asset" src="'+x.asset+'" alt="学生样卷及批注">').join('')+'</details>';return s;}
function show(id){const q=B.items.find(x=>x.id===id);if(!q)return;const p=P[q.parent];const map=Object.fromEntries(p.blocks.map(b=>[b.id,b]));let ids=[...q.depends_on];if(id==='Q21')ids=['21.aside','21.m1','21.m2','21.ask'];let s='<section class="card"><h2>2026海淀一模 第 '+q.parent+' 题'+(id.includes('-')?' · '+esc(id):'')+'</h2><p class="meta">当前取用 '+q.points+' 分 · 原卷第 '+q.source_pages.join('、')+' 页<br>'+q.modules.map(m=>'<span class="tag">'+esc(m)+'</span>').join('')+'</p>';if(q.cross_module_note)s+='<p class="limits">'+esc(q.cross_module_note)+'</p>';if(q.task_note)s+='<p class="limits">'+esc(q.task_note)+'</p>';s+='<h3>原题</h3><div class="question '+q.kind+'">'+ids.map(k=>block(map[k])).join('')+'</div>';if(q.kind==='choice')s+='<div class="result">答案：'+esc(q.answer)+'</div><p class="small">依据细则第 1 页答案键；未入选不自动表示题肢错误。</p>';s+='<p class="small"><a href="packets/'+id+'.md">打开这一题的完整取用包</a></p><details class="source"><summary>对照原卷版面</summary>'+p.question_bbox.map(x=>'<img src="'+x.asset+'" alt="第'+q.parent+'题原卷截图">').join('')+'</details>';if(p.notes?.length)s+='<p class="limits">'+esc(p.notes.join('；'))+'</p>';s+='</section>';for(const rid of q.rubric_ids)s+='<section class="card rubric"><h3>正式评分材料 · '+rid+'</h3>'+rubric(R[rid])+'</section>';document.querySelector('#main').innerHTML=s;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.id===id));history.replaceState(null,'','#'+id);}
function filter(){const m=document.querySelector('#module').value,t=document.querySelector('#search').value.trim().toLowerCase();const a=B.items.filter(x=>(!m||x.modules.includes(m))&&(!t||[x.id,...x.tags].join(' ').toLowerCase().includes(t)));document.querySelector('#count').textContent=a.length+' 个取用单元';document.querySelector('#nav').innerHTML=a.map(q=>'<button data-id="'+q.id+'">'+q.id+' · '+(q.kind==='choice'?'选择题':'主观题')+'<small>'+esc(q.tags.slice(0,3).join(' · '))+'</small></button>').join('');document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>show(b.dataset.id));const current=location.hash.slice(1);if(a.length)show(a.some(q=>q.id===current)?current:a[0].id);else document.querySelector('#main').innerHTML='<section class="card"><h2>没有匹配的题目</h2><p>请调整教材或搜索词。</p></section>';}
[...new Set(B.items.flatMap(x=>x.modules))].sort().forEach(m=>{const o=document.createElement('option');o.value=m;o.textContent=m;document.querySelector('#module').append(o)});document.querySelector('#module').onchange=filter;document.querySelector('#search').oninput=filter;if(!location.hash)location.hash='Q18-2';filter();
</script></html>'''
page=page.replace('__BANK__',json.dumps(minimal,ensure_ascii=False).replace('</','<\\/'))
(ROOT/'00_题库试用.html').write_text(page)
print('已生成本地题库浏览页')
